test('lineTotal consistency across multiple calls', () => {
  const line = { qty: 7, unitPrice: 143 };
  const result1 = lineTotal(line);
  const result2 = lineTotal(line);
  assert.equal(result1, result2);
});

test('invoiceTotals applies bulk discount for qty >= 10', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.subtotal, 1000);
  assert.ok(result.discount > 0);
  assert.equal(result.discount, 25);
});

test('invoiceTotals does not apply bulk discount for qty < 10', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.subtotal, 900);
  assert.equal(result.discount, 0);
  assert.equal(result.total, 900);
});

test('invoiceTotals bulk discount is 2.5% of amount after line discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 0 }],
  };
  const result = invoiceTotals(invoice);
  const subtotal = 10000;
  const lineDiscount = 1000;
  const afterLineDiscount = 9000;
  const bulkDiscount = 225;
  const expectedDiscount = lineDiscount + bulkDiscount;
  assert.equal(result.discount, expectedDiscount);
});

test('invoiceTotals VAT is on amount after both discounts', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);
  const subtotal = 10000;
  const bulkDiscount = 250;
  const afterBulkDiscount = 9750;
  const vat = Math.round(afterBulkDiscount * 0.21);
  assert.ok(result.vat > 0);
});

test('invoiceTotals bulk discount with exactly 10 units', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
  };
  const result = invoiceTotals(invoice);
  assert.ok(result.discount > 0);
});

test('invoiceTotals no bulk discount with exactly 9 units', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.discount, 0);
});

test('invoiceTotals bulk discount with large quantity', () => {
  const invoice = {
    lines: [{ qty: 1000, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
  };
  const result = invoiceTotals(invoice);
  const subtotal = 100000;
  const bulkDiscount = 2500;
  assert.equal(result.discount, bulkDiscount);
});

test('invoiceTotals multiple lines with different quantities', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 100, discountPercent: 0, vatRate: 0 },
      { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 },
      { qty: 15, unitPrice: 100, discountPercent: 0, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  const subtotal = 3000;
  const line1Discount = 0;
  const line2Discount = 250;
  const line3Discount = 375;
  const totalDiscount = line1Discount + line2Discount + line3Discount;
  assert.equal(result.discount, totalDiscount);
});

test('invoiceTotals bulk discount with line discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 100, discountPercent: 10, vatRate: 0 }],
  };
  const result = invoiceTotals(invoice);
  const subtotal = 1000;
  const lineDiscount = 100;
  const afterLineDiscount = 900;
  const bulkDiscount = 22;
  const expectedDiscount = lineDiscount + bulkDiscount;
  assert.equal(result.discount, expectedDiscount);
});

test('invoiceTotals bulk discount combined with VAT correctly', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);
  const subtotal = 1000;
  const bulkDiscount = 25;
  const afterBulkDiscount = 975;
  const vat = Math.round(afterBulkDiscount * 0.21);
  const expectedTotal = afterBulkDiscount + vat;
  assert.equal(result.total, expectedTotal);
});

test('invoiceTotals bulk discount applied correctly with multiple conditions', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 200, discountPercent: 5, vatRate: 21 },
      { qty: 8, unitPrice: 150, discountPercent: 5, vatRate: 9 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.ok(result.discount > 0);
  assert.ok(result.vat > 0);
  assert.ok(result.total > 0);
});

test('invoiceTotals discount field includes both line and bulk discounts', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 5, vatRate: 0 }],
  };
  const result = invoiceTotals(invoice);
  const subtotal = 10000;
  const lineDiscount = 500;
  const afterLineDiscount = 9500;
  const bulkDiscount = 237;
  assert.equal(result.discount, lineDiscount + bulkDiscount);
});

