  assert.equal(result.ok, true);
  const voucherResult = applyVoucher(result.value, {
    code: 'SUMMER20',
    amount: 2000,
  });

  assert.equal(voucherResult.ok, true);
  assert.equal(voucherResult.value.voucher.code, 'SUMMER20');
  assert.equal(voucherResult.value.voucher.amount, 2000);
});

test('invoiceTotals includes voucher', () => {
