    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const withVoucher = applyVoucher(result.value, {
    code: 'SUMMER20',
    amount: 2000,
  });

  assert.equal(withVoucher.ok, true);
  const totals = invoiceTotals(withVoucher.value);

  // 1 × €95.00 + 21% VAT = €114.95, minus €20 voucher = €94.95
  assert.equal(totals.voucher, 2000);
  assert.equal(totals.subtotal, 9500);
  assert.equal(totals.vat, 1995);
  assert.equal(totals.total, 9495);
});

