test('applyVoucher applies voucher to draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const voucherResult = applyVoucher(result.value, {
    code: 'SUMMER20',
    amount: 2000,
  });

  assert.equal(voucherResult.ok, true);
  assert.equal(voucherResult.value.voucher.code, 'SUMMER20');
  assert.equal(voucherResult.value.voucher.amount, 2000);
});

test('invoiceTotals includes voucher', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;
  const totals = invoiceTotals(invoice);

  assert.equal(totals.voucher, 0);
  // 1 × €95.00 + 21% VAT = €114.95, no voucher
  assert.equal(totals.total, 11495);
});

test('invoiceTotals subtracts voucher from total', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const withVoucher = applyVoucher(result.value, {
    code: 'SUMMER20',
    amount: 2000,
  });

  assert.equal(withVoucher.ok, true);
  const totals = invoiceTotals(withVoucher.value);

  // 1 × €95.00 + 21% VAT = €114.95, minus €20 voucher = €94.95
  assert.equal(totals.voucher, 2000);
  assert.equal(totals.subtotal, 9500);
  assert.equal(totals.vat, 1995);
  assert.equal(totals.total, 9495);
});

test('applyVoucher fails on non-draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const voucherResult = applyVoucher(issued.value, {
    code: 'SUMMER20',
    amount: 2000,
  });

  assert.equal(voucherResult.ok, false);
  assert.equal(voucherResult.error, 'NOT_DRAFT');
});

test('applyVoucher fails with VOUCHER_EXISTS on second voucher', () => {
