  });

  assert.equal(withVoucher1.ok, true);

  const withVoucher2 = applyVoucher(withVoucher1.value, {
    code: 'EXTRA10',
    amount: 1000,
  });

  assert.equal(withVoucher2.ok, false);
  assert.equal(withVoucher2.error, 'VOUCHER_EXISTS');
});

