test('createInvoice does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  };
  const inputLines = input.lines;

  createInvoice(input);

  assert.equal(input.customerId, 'C-001');
  assert.equal(input.issueDate, '2026-10-07');
  assert.strictEqual(input.lines, inputLines);
  assert.equal(input.lines[0].sku, 'DEV-HOUR');
  assert.equal(input.lines[0].qty, 5);
  assert.equal(Object.keys(input.lines[0]).length, 2);
});

test('createInvoice with various SKUs from catalogue', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'PRINT-A4', qty: 500 },
      { sku: 'WORKSHOP-DAY', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].name, 'Logo package');
  assert.equal(result.value.lines[0].unitPrice, 120000);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].name, 'Printed flyer A4 (each)');
  assert.equal(result.value.lines[1].unitPrice, 37);
  assert.equal(result.value.lines[1].vatRate, 9);
  assert.equal(result.value.lines[2].name, 'Brand workshop (day, VAT exempt)');
  assert.equal(result.value.lines[2].unitPrice, 60000);
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
});

test('lineTotal with single qty', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 6000 }), 6000);
});

test('invoiceTotals sums line totals', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, unitPrice: 9500, name: 'Development (hour)', vatRate: 21, discountPercent: 0 },
      { sku: 'STICKER', qty: 100, unitPrice: 50, name: 'Sticker sheet', vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 5 × €95.00 = €475.00 (no bulk discount, qty < 10), 21% VAT = €99.75
  // Line 2: 100 × €0.50 = €50.00, bulk discount 2.5% = €1.25, VAT on €48.75 = €10.24
  // Subtotal: €525.00, Discount: €1.25, VAT: €109.99, Total: €633.74
  assert.equal(totals.subtotal, 52500);
  assert.equal(totals.discount, 125);
  assert.equal(totals.vat, 10999);
  assert.equal(totals.total, 63374);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'LOGO-PACK', qty: 1, unitPrice: 120000, name: 'Logo package', vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // 1 × €1,200.00 = €1,200.00
  // 21% VAT = €252.00
  // Total = €1,452.00
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 25200);
  assert.equal(totals.total, 145200);
});

test('invoiceTotals with multiple high-value items', () => {
  const invoice = {
    customerId: 'C-005',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'BRAND-BOOK', qty: 2, unitPrice: 245000, name: 'Brand guidelines document', vatRate: 21, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', qty: 3, unitPrice: 60000, name: 'Brand workshop (day, VAT exempt)', vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const subtotal = (2 * 245000) + (3 * 60000);
  // Line 1: 2 × €2,450.00 = €4,900.00, 21% VAT = €1,029.00
  // Line 2: 3 × €600.00 = €1,800.00, 0% VAT = €0.00
  // Subtotal: €6,700.00, VAT: €1,029.00, Total: €7,729.00
  assert.equal(totals.subtotal, subtotal);
