  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // Line 1: 1 × €95.00 = €95.00 (no bulk), 21% VAT = €19.95
  // Line 2: 100 × €0.37 = €37.00, bulk 2.5% = €0.92, 9% VAT on €36.08 = €3.25
  // Line 3: 1 × €600.00 = €600.00 (no bulk), 0% VAT = €0.00
  // Subtotal: €732.00, Discount: €0.92
  // VAT: €23.20
  // Total: €754.28
  assert.equal(totals.subtotal, 73200);
  assert.equal(totals.discount, 92);
  assert.equal(totals.vat, 2320);
  assert.equal(totals.total, 75428);
});

