  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // Line 1: 3 × €95.00 = €285.00, 21% VAT = €59.85
  // Line 2: 2 × €60.00 = €120.00, 21% VAT = €25.20
  // Subtotal: €405.00, VAT: €85.05, Total: €490.05
  assert.equal(totals.subtotal, 40500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 8505);
  assert.equal(totals.total, 49005);
});

test('createInvoice accepts discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
