test('invoiceTotals calculates discount correctly', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 10 × €95.00 = €950.00
  // 10% line discount = €95.00, amount after = €855.00
  // Bulk discount 2.5% on €855.00 = €21.38
  // Amount after both discounts = €833.62
  // 21% VAT on €833.62 = €175.06
  // Total = €950.00 - €116.38 + €175.06 = €1,008.68
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 11638);
  assert.equal(totals.vat, 17506);
  assert.equal(totals.total, 100868);
});

test('invoiceTotals with multiple lines and different discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'STICKER', qty: 100, discountPercent: 25 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // Line 1: 10 × €95.00 = €950.00, 10% discount = €95.00, bulk 2.5% = €21.38, VAT = €175.06
  // Line 2: 100 × €0.50 = €50.00, 25% discount = €12.50, bulk 2.5% = €0.94, VAT = €7.68
  // Subtotal: €1,000.00, Discount: €129.82, VAT: €182.74, Total: €1,052.92
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 12982);
  assert.equal(totals.vat, 18274);
  assert.equal(totals.total, 105292);
});

test('invoiceTotals with decimal discount percentages', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 12.5 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 1 × €95.00 = €95.00
  // 12.5% discount = €11.875 -> €11.88
  // Amount after discount = €83.12
  // 21% VAT on €83.12 = €17.455 -> €17.46
  // Total = €95.00 - €11.88 + €17.46 = €100.58
  assert.equal(totals.subtotal, 9500);
  assert.equal(totals.discount, 1188);
  assert.equal(totals.vat, 1746);
  assert.equal(totals.total, 10058);
});

test('invoiceTotals clamps negative amounts to 0', () => {
  // This shouldn't happen in normal usage, but we test the clamping
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'STICKER', qty: 1, unitPrice: 50, name: 'Sticker sheet', vatRate: 21, discountPercent: 100 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // 1 × €0.50 = €0.50
  // 100% discount = €0.50
  // Total = €0.50 - €0.50 = €0.00 (clamped)
  assert.equal(totals.subtotal, 50);
  assert.equal(totals.discount, 50);
  assert.equal(totals.total, 0);
});

