  assert.equal(addLine(invoice, { sku: 'STICKER', qty: 100, discountPercent: -10 }).error, 'DISCOUNT_INVALID');
  assert.equal(addLine(invoice, { sku: 'STICKER', qty: 100, discountPercent: 101 }).error, 'DISCOUNT_INVALID');
  assert.equal(addLine(invoice, { sku: 'STICKER', qty: 100, discountPercent: '50' }).error, 'DISCOUNT_INVALID');
