  const result = addLine(invoice, { sku: 'STICKER', qty: 50, discountPercent: 25 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].qty, 150);
  assert.equal(result.value.lines[0].discountPercent, 25);
});

test('addLine keeps existing discount if not specified', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
