test('invoiceTotals with 9% VAT rate', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'PRINT-A3', qty: 10 },
    ],
  });

  assert.equal(result.ok, true);
