  // 10 × €2.49 = €24.90
  // 0% discount
  // 9% VAT on €24.90 = €2.241 -> €2.24
  // Total = €24.90 + €2.24 = €27.14
  assert.equal(totals.subtotal, 2490);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 224);
  assert.equal(totals.total, 2714);

