test('invoiceTotals calculates discount correctly', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 10 × €95.00 = €950.00
  // 10% line discount = €95.00, amount after = €855.00
  // Bulk discount 2.5% on €855.00 = €21.38
  // Amount after both discounts = €833.62
  // 21% VAT on €833.62 = €175.06
  // Total = €950.00 - €116.38 + €175.06 = €1,008.68
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 11638);
  assert.equal(totals.vat, 17506);
  assert.equal(totals.total, 100868);
});

