  // Line 1: 5 × €95.00 = €475.00, 10% discount = €47.50, €427.50 after discount
  //         21% VAT on €427.50 = €89.775 -> €89.78
  // Line 2: 200 × €0.37 = €74.00, 0% discount, €74.00 after discount
  //         9% VAT on €74.00 = €6.66
  // Subtotal: €549.00
  // Discount: €47.50
  // VAT: €96.44
  // Total: €597.94
  assert.equal(totals.subtotal, 54900);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 9644);
  assert.equal(totals.total, 59794);
});

