test('renderInvoiceText shows VAT line when VAT > 0', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
