  // 1 × €95.00, 21% VAT = €19.95
  // Total = €95.00 + €19.95 = €114.95
  assert(text.includes('VAT: €19.95'));
  assert(text.includes('Total: €114.95'));
});

test('renderInvoiceText does not show VAT line when VAT = 0', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
