  assert(text.includes('Total: €600.00'));
});

test('renderInvoiceText with mixed VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // Should include VAT line and correct total
  // Line 1: €95.00, VAT €19.95
  // Line 2: €37.00 - €0.92 bulk discount, VAT €3.25
  // Line 3: €600.00, no VAT
  // Total: €754.28
  assert(text.includes('VAT:'));
  assert(text.includes('Total: €754.28'));
});

test('renderInvoiceText with discount and VAT', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // 1 × €1,200.00
  // 5% tier discount = €60.00
  // 21% VAT on €1,140.00 = €239.40
  // Total = €1,200.00 - €60.00 + €239.40 = €1,379.40
  assert(text.includes('1 × Logo package'));
  assert(text.includes('€1,200.00'));
  assert(text.includes('VAT: €239.40'));
  assert(text.includes('Total: €1,379.40'));
});

