      customerId: 'C-001',
      issueDate: '2026-13-01',
      lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    }).error,
    'DATE_INVALID'
  );

  assert.equal(
    createInvoice({
      customerId: 'C-001',
      issueDate: 'not-a-date',
      lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    }).error,
    'DATE_INVALID'
  );
});

