  assert.equal(result.ok, true);

  const voucherResult = applyVoucher(result.value, {
    code: 'SUMMER20',
    amount: 0,
  });

  assert.equal(voucherResult.ok, false);
  assert.equal(voucherResult.error, 'AMOUNT_INVALID');
});

test('applyVoucher does not mutate input invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;

  applyVoucher(invoice, {
    code: 'SUMMER20',
    amount: 2000,
  });

  assert.equal(invoice.voucher, undefined);
});

test('voucher reduces total below cost', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'STICKER', qty: 100 },
    ],
  });

  assert.equal(result.ok, true);
  const withVoucher = applyVoucher(result.value, {
    code: 'FREE',
    amount: 6050,
  });

  assert.equal(withVoucher.ok, true);
  const totals = invoiceTotals(withVoucher.value);

  // 100 × €0.50 + 21% VAT = €60.50, minus €60.50 voucher = €0.00
  assert.equal(totals.total, 0);
});
